// Generates backend/apps-script/AirportsV2.gs from src/data/airports.js, so the backend and
// the frontend share ONE airport → IANA time-zone table. Run: node scripts/gen-airports-gs.mjs
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { AIRPORTS } from '../src/data/airports.js';

export function renderAirportsGs() {
  const rows = Object.keys(AIRPORTS).sort().map((code) => `  ${code}: '${AIRPORTS[code].tz}',`);
  return [
    '// GENERATED by scripts/gen-airports-gs.mjs from src/data/airports.js. Do not edit by hand.',
    '// Airport (IATA) → IANA time zone for the fc.roster v2 contract. Unknown airports have no',
    '// entry: their local times are reported as unknown, never guessed.',
    'const FCV2_AIRPORT_TZ_ = Object.freeze({',
    ...rows,
    '});',
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(new URL('../backend/apps-script/AirportsV2.gs', import.meta.url), renderAirportsGs());
  console.log(`AirportsV2.gs: ${Object.keys(AIRPORTS).length} airports`);
}
